-- ===========================================================================
--  Indonesia Car Sales Analytics — SQL Project
--  Sales Performance · Market Share · Brand Analysis · Regional Demand
--
--  Dialect : PostgreSQL  (13+)
--  Dataset : 100% synthetic / fictional — no real records used
--  Period  : 2020-01-01  to  2025-12-31
--  Volume  : 10,000+ sales transactions  |  10 related tables
--
--  Structure of this file
--    1.  DROP & CREATE TABLE statements              (schema)
--    2.  INSERT statements with full synthetic data  (~45,000 rows)
--    3.  Twenty analytical queries grouped by theme  (Q1–Q20)
--
--  How to run
--    psql -U <user> -d <database> -f indonesia_car_sales_analytics.sql
--
--  Author  : Data Analytics Portfolio
-- ===========================================================================

\timing on

-- ===========================================================================
--  SECTION 1 :  SCHEMA  (drop + create, in dependency order)
-- ===========================================================================

DROP TABLE IF EXISTS after_sales_service  CASCADE;
DROP TABLE IF EXISTS financing            CASCADE;
DROP TABLE IF EXISTS marketing_campaigns  CASCADE;
DROP TABLE IF EXISTS inventory            CASCADE;
DROP TABLE IF EXISTS sales_targets        CASCADE;
DROP TABLE IF EXISTS sales_transactions   CASCADE;
DROP TABLE IF EXISTS vehicles             CASCADE;
DROP TABLE IF EXISTS dealers              CASCADE;
DROP TABLE IF EXISTS customers            CASCADE;
DROP TABLE IF EXISTS brands               CASCADE;

CREATE TABLE brands (
    brand_id        INT PRIMARY KEY,
    brand_name      VARCHAR(50)  NOT NULL UNIQUE,
    country_origin  VARCHAR(50),
    brand_segment   VARCHAR(20)
);

CREATE TABLE customers (
    customer_id     INT PRIMARY KEY,
    customer_name   VARCHAR(100) NOT NULL,
    gender          VARCHAR(10),
    age             INT,
    occupation      VARCHAR(50),
    income_segment  VARCHAR(20),
    city            VARCHAR(50),
    province        VARCHAR(50),
    customer_type   VARCHAR(20)
);

CREATE TABLE dealers (
    dealer_id       INT PRIMARY KEY,
    dealer_name     VARCHAR(100) NOT NULL,
    city            VARCHAR(50),
    province        VARCHAR(50),
    region          VARCHAR(30),
    dealer_type     VARCHAR(20)
);

CREATE TABLE vehicles (
    vehicle_id      INT PRIMARY KEY,
    brand           VARCHAR(50)  NOT NULL,
    model           VARCHAR(50),
    variant         VARCHAR(50),
    vehicle_type    VARCHAR(20),
    fuel_type       VARCHAR(20),
    transmission    VARCHAR(20),
    engine_capacity INT,
    production_year INT,
    price_category  VARCHAR(20),
    CONSTRAINT fk_vehicle_brand
        FOREIGN KEY (brand) REFERENCES brands (brand_name)
);

CREATE TABLE sales_transactions (
    transaction_id   INT PRIMARY KEY,
    transaction_date DATE NOT NULL,
    customer_id      INT  NOT NULL,
    vehicle_id       INT  NOT NULL,
    dealer_id        INT  NOT NULL,
    quantity         INT  DEFAULT 1,
    unit_price       DECIMAL(15,2),
    discount_amount  DECIMAL(15,2) DEFAULT 0,
    tax_amount       DECIMAL(15,2) DEFAULT 0,
    total_revenue    DECIMAL(15,2),
    payment_method   VARCHAR(20),
    sales_channel    VARCHAR(20),
    CONSTRAINT fk_txn_customer FOREIGN KEY (customer_id) REFERENCES customers (customer_id),
    CONSTRAINT fk_txn_vehicle  FOREIGN KEY (vehicle_id)  REFERENCES vehicles  (vehicle_id),
    CONSTRAINT fk_txn_dealer   FOREIGN KEY (dealer_id)   REFERENCES dealers   (dealer_id)
);

CREATE TABLE sales_targets (
    target_id          INT PRIMARY KEY,
    dealer_id          INT NOT NULL,
    target_month       INT CHECK (target_month BETWEEN 1 AND 12),
    target_year        INT,
    sales_target_units INT,
    revenue_target     DECIMAL(18,2),
    CONSTRAINT fk_target_dealer FOREIGN KEY (dealer_id) REFERENCES dealers (dealer_id)
);

CREATE TABLE inventory (
    inventory_id    INT PRIMARY KEY,
    dealer_id       INT NOT NULL,
    vehicle_id      INT NOT NULL,
    stock_available INT,
    stock_in        INT,
    stock_out       INT,
    inventory_month DATE,
    CONSTRAINT fk_inv_dealer  FOREIGN KEY (dealer_id)  REFERENCES dealers  (dealer_id),
    CONSTRAINT fk_inv_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles (vehicle_id)
);

CREATE TABLE marketing_campaigns (
    campaign_id      INT PRIMARY KEY,
    campaign_name    VARCHAR(100),
    brand            VARCHAR(50),
    campaign_channel VARCHAR(30),
    start_date       DATE,
    end_date         DATE,
    campaign_cost    DECIMAL(18,2),
    target_region    VARCHAR(30)
);

CREATE TABLE financing (
    financing_id       INT PRIMARY KEY,
    transaction_id     INT NOT NULL,
    financing_company  VARCHAR(50),
    down_payment       DECIMAL(15,2),
    loan_amount        DECIMAL(15,2),
    tenor_months       INT,
    interest_rate      DECIMAL(5,2),
    installment_amount DECIMAL(15,2),
    CONSTRAINT fk_fin_txn FOREIGN KEY (transaction_id)
        REFERENCES sales_transactions (transaction_id)
);

CREATE TABLE after_sales_service (
    service_id                  INT PRIMARY KEY,
    customer_id                 INT NOT NULL,
    vehicle_id                  INT NOT NULL,
    dealer_id                   INT NOT NULL,
    service_date                DATE,
    service_type                VARCHAR(30),
    service_cost                DECIMAL(15,2),
    customer_satisfaction_score INT CHECK (customer_satisfaction_score BETWEEN 1 AND 5),
    CONSTRAINT fk_svc_customer FOREIGN KEY (customer_id) REFERENCES customers (customer_id),
    CONSTRAINT fk_svc_vehicle  FOREIGN KEY (vehicle_id)  REFERENCES vehicles  (vehicle_id),
    CONSTRAINT fk_svc_dealer   FOREIGN KEY (dealer_id)   REFERENCES dealers   (dealer_id)
);

-- Helpful indexes for analytical queries
CREATE INDEX idx_txn_date     ON sales_transactions (transaction_date);
CREATE INDEX idx_txn_vehicle  ON sales_transactions (vehicle_id);
CREATE INDEX idx_txn_dealer   ON sales_transactions (dealer_id);
CREATE INDEX idx_txn_customer ON sales_transactions (customer_id);
CREATE INDEX idx_inv_month    ON inventory (inventory_month);
CREATE INDEX idx_svc_date     ON after_sales_service (service_date);


