-- ===========================================================================
--  SECTION 3 :  ANALYTICAL QUERIES  (Q1 – Q20)
--
--  Each query is self-contained and can be run on its own.
--  Themes:
--    10.1  Overall Sales Performance        (Q1, Q2)
--    10.2  Brand Analysis                   (Q3, Q4, Q5)
--    10.3  Model & Vehicle-Type             (Q6, Q7)
--    10.4  Regional Demand                  (Q8, Q9)
--    10.5  Dealer Performance vs Target     (Q10)
--    10.6  Customer Segmentation            (Q11, Q12)
--    10.7  Price, Discount & Revenue        (Q13)
--    10.8  Payment & Financing              (Q14)
--    10.9  Inventory Efficiency             (Q15)
--    10.10 Marketing Campaign ROI           (Q16)
--    10.11 After-Sales & Retention          (Q17)
--    10.12 Market Share Over Time           (Q18)
--    10.13 Year-over-Year Growth            (Q19)
--          Executive Summary                (Q20)
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- Q1.  Headline KPIs — units, revenue, average selling price
-- ---------------------------------------------------------------------------
SELECT
    SUM(quantity)                              AS total_units_sold,
    SUM(total_revenue)                         AS total_revenue,
    ROUND(SUM(total_revenue) / SUM(quantity))  AS avg_selling_price,
    SUM(discount_amount)                       AS total_discounts,
    SUM(tax_amount)                            AS total_tax_collected
FROM sales_transactions;


-- ---------------------------------------------------------------------------
-- Q2.  Monthly & yearly sales trend
-- ---------------------------------------------------------------------------
SELECT
    EXTRACT(YEAR  FROM transaction_date) AS sales_year,
    EXTRACT(MONTH FROM transaction_date) AS sales_month,
    SUM(quantity)      AS units_sold,
    SUM(total_revenue) AS revenue
FROM sales_transactions
GROUP BY EXTRACT(YEAR FROM transaction_date),
         EXTRACT(MONTH FROM transaction_date)
ORDER BY sales_year, sales_month;


-- ---------------------------------------------------------------------------
-- Q3.  Brand ranking by units and by revenue
-- ---------------------------------------------------------------------------
SELECT
    v.brand,
    SUM(st.quantity)      AS units_sold,
    SUM(st.total_revenue) AS revenue,
    RANK() OVER (ORDER BY SUM(st.quantity)      DESC) AS rank_by_units,
    RANK() OVER (ORDER BY SUM(st.total_revenue) DESC) AS rank_by_revenue
FROM sales_transactions st
JOIN vehicles v ON v.vehicle_id = st.vehicle_id
GROUP BY v.brand
ORDER BY units_sold DESC;


-- ---------------------------------------------------------------------------
-- Q4.  Brand market share (% of total units)
-- ---------------------------------------------------------------------------
SELECT
    v.brand,
    SUM(st.quantity) AS units_sold,
    ROUND(100.0 * SUM(st.quantity)
        / SUM(SUM(st.quantity)) OVER (), 2) AS market_share_pct
FROM sales_transactions st
JOIN vehicles v ON v.vehicle_id = st.vehicle_id
GROUP BY v.brand
ORDER BY market_share_pct DESC;


-- ---------------------------------------------------------------------------
-- Q5.  Brand year-over-year growth (using LAG)
-- ---------------------------------------------------------------------------
WITH brand_year AS (
    SELECT v.brand,
           EXTRACT(YEAR FROM st.transaction_date) AS yr,
           SUM(st.quantity) AS units
    FROM sales_transactions st
    JOIN vehicles v ON v.vehicle_id = st.vehicle_id
    GROUP BY v.brand, EXTRACT(YEAR FROM st.transaction_date)
)
SELECT brand, yr, units,
       LAG(units) OVER (PARTITION BY brand ORDER BY yr) AS prev_year_units,
       ROUND(100.0 * (units - LAG(units) OVER (PARTITION BY brand ORDER BY yr))
           / NULLIF(LAG(units) OVER (PARTITION BY brand ORDER BY yr), 0), 1) AS yoy_growth_pct
FROM brand_year
ORDER BY brand, yr;


-- ---------------------------------------------------------------------------
-- Q6.  Best-selling models (top 10)
-- ---------------------------------------------------------------------------
SELECT v.brand, v.model,
       SUM(st.quantity)      AS units_sold,
       SUM(st.total_revenue) AS revenue
FROM sales_transactions st
JOIN vehicles v ON v.vehicle_id = st.vehicle_id
GROUP BY v.brand, v.model
ORDER BY units_sold DESC
LIMIT 10;


-- ---------------------------------------------------------------------------
-- Q7.  Vehicle type / fuel / transmission performance
-- ---------------------------------------------------------------------------
SELECT v.vehicle_type, v.fuel_type, v.transmission,
       SUM(st.quantity)                                   AS units_sold,
       ROUND(100.0 * SUM(st.quantity)
           / SUM(SUM(st.quantity)) OVER (), 2)            AS share_pct
FROM sales_transactions st
JOIN vehicles v ON v.vehicle_id = st.vehicle_id
GROUP BY v.vehicle_type, v.fuel_type, v.transmission
ORDER BY units_sold DESC;


-- ---------------------------------------------------------------------------
-- Q8.  Sales by region, province, city
-- ---------------------------------------------------------------------------
SELECT d.region, d.province, d.city,
       SUM(st.quantity)      AS units_sold,
       SUM(st.total_revenue) AS revenue
FROM sales_transactions st
JOIN dealers d ON d.dealer_id = st.dealer_id
GROUP BY d.region, d.province, d.city
ORDER BY units_sold DESC;


-- ---------------------------------------------------------------------------
-- Q9.  Dealer-expansion opportunity (units per dealer vs network avg)
-- ---------------------------------------------------------------------------
WITH prov AS (
    SELECT d.province,
           SUM(st.quantity)              AS units_sold,
           COUNT(DISTINCT d.dealer_id)   AS dealer_count
    FROM sales_transactions st
    JOIN dealers d ON d.dealer_id = st.dealer_id
    GROUP BY d.province
)
SELECT province, units_sold, dealer_count,
       ROUND(units_sold * 1.0 / dealer_count, 1) AS units_per_dealer,
       CASE WHEN units_sold * 1.0 / dealer_count >
                 AVG(units_sold * 1.0 / dealer_count) OVER ()
            THEN 'Expansion Candidate' ELSE 'Adequately Served' END AS recommendation
FROM prov
ORDER BY units_per_dealer DESC;


-- ---------------------------------------------------------------------------
-- Q10. Dealer target achievement (Overperform / On Target / Underperform)
-- ---------------------------------------------------------------------------
WITH actuals AS (
    SELECT dealer_id,
           EXTRACT(YEAR  FROM transaction_date) AS yr,
           EXTRACT(MONTH FROM transaction_date) AS mo,
           SUM(quantity) AS actual_units
    FROM sales_transactions
    GROUP BY dealer_id,
             EXTRACT(YEAR FROM transaction_date),
             EXTRACT(MONTH FROM transaction_date)
)
SELECT d.dealer_name, t.target_year, t.target_month,
       t.sales_target_units, COALESCE(a.actual_units, 0) AS actual_units,
       ROUND(100.0 * COALESCE(a.actual_units,0)
           / NULLIF(t.sales_target_units,0), 1) AS achievement_pct,
       CASE
           WHEN COALESCE(a.actual_units,0) >= 1.1 * t.sales_target_units THEN 'Overperform'
           WHEN COALESCE(a.actual_units,0) >=       t.sales_target_units THEN 'On Target'
           ELSE 'Underperform'
       END AS status
FROM sales_targets t
JOIN dealers d  ON d.dealer_id = t.dealer_id
LEFT JOIN actuals a
       ON a.dealer_id = t.dealer_id
      AND a.yr = t.target_year
      AND a.mo = t.target_month
ORDER BY achievement_pct DESC;


-- ---------------------------------------------------------------------------
-- Q11. Customer segmentation by age band & income
-- ---------------------------------------------------------------------------
SELECT
    CASE
        WHEN age < 25 THEN '<25'
        WHEN age BETWEEN 25 AND 34 THEN '25-34'
        WHEN age BETWEEN 35 AND 44 THEN '35-44'
        WHEN age BETWEEN 45 AND 54 THEN '45-54'
        ELSE '55+'
    END AS age_band,
    c.income_segment,
    COUNT(DISTINCT st.transaction_id) AS purchases,
    SUM(st.total_revenue)             AS revenue
FROM sales_transactions st
JOIN customers c ON c.customer_id = st.customer_id
WHERE c.customer_type = 'Individual'
GROUP BY 1, c.income_segment
ORDER BY revenue DESC;


-- ---------------------------------------------------------------------------
-- Q12. Repeat-customer analysis (One-time / Repeat / Loyal)
-- ---------------------------------------------------------------------------
WITH cust_orders AS (
    SELECT customer_id,
           COUNT(*)              AS purchase_count,
           SUM(total_revenue)    AS lifetime_revenue
    FROM sales_transactions
    GROUP BY customer_id
)
SELECT
    CASE WHEN purchase_count = 1 THEN 'One-time'
         WHEN purchase_count BETWEEN 2 AND 3 THEN 'Repeat'
         ELSE 'Loyal (4+)' END AS customer_tier,
    COUNT(*)                    AS customers,
    SUM(lifetime_revenue)       AS revenue,
    ROUND(AVG(lifetime_revenue))AS avg_lifetime_value
FROM cust_orders
GROUP BY 1
ORDER BY revenue DESC;


-- ---------------------------------------------------------------------------
-- Q13. Average price, discount & discount rate by brand
-- ---------------------------------------------------------------------------
SELECT v.brand,
       ROUND(AVG(st.unit_price))                          AS avg_list_price,
       ROUND(AVG(st.discount_amount))                     AS avg_discount,
       ROUND(100.0 * SUM(st.discount_amount)
           / NULLIF(SUM(st.quantity * st.unit_price),0), 2) AS discount_rate_pct,
       SUM(st.total_revenue)                              AS net_revenue
FROM sales_transactions st
JOIN vehicles v ON v.vehicle_id = st.vehicle_id
GROUP BY v.brand
ORDER BY discount_rate_pct DESC;


-- ---------------------------------------------------------------------------
-- Q14. Cash vs Credit, with financing profile
-- ---------------------------------------------------------------------------
SELECT st.payment_method,
       COUNT(*)                       AS transactions,
       ROUND(100.0 * COUNT(*)
           / SUM(COUNT(*)) OVER (), 1) AS share_pct,
       ROUND(AVG(f.down_payment))     AS avg_down_payment,
       ROUND(AVG(f.tenor_months), 1)  AS avg_tenor_months,
       ROUND(AVG(f.interest_rate), 2) AS avg_interest_rate
FROM sales_transactions st
LEFT JOIN financing f ON f.transaction_id = st.transaction_id
GROUP BY st.payment_method;


-- ---------------------------------------------------------------------------
-- Q15. Inventory turnover & restock flag
-- ---------------------------------------------------------------------------
SELECT v.brand, v.model,
       SUM(i.stock_out)                                       AS total_sold,
       ROUND(AVG(i.stock_available), 1)                       AS avg_stock_on_hand,
       ROUND(SUM(i.stock_out) * 1.0
           / NULLIF(AVG(i.stock_available),0), 2)             AS turnover_ratio,
       CASE
           WHEN AVG(i.stock_available) > 2 * NULLIF(AVG(i.stock_out),0)
               THEN 'Overstocked - Slow Mover'
           WHEN AVG(i.stock_available) < 0.5 * NULLIF(AVG(i.stock_out),0)
               THEN 'Understocked - Restock'
           ELSE 'Balanced'
       END AS stock_status
FROM inventory i
JOIN vehicles v ON v.vehicle_id = i.vehicle_id
GROUP BY v.brand, v.model
ORDER BY turnover_ratio DESC NULLS LAST;


-- ---------------------------------------------------------------------------
-- Q16. Marketing campaign ROI
-- ---------------------------------------------------------------------------
WITH campaign_rev AS (
    SELECT mc.campaign_id, mc.campaign_name, mc.brand,
           mc.campaign_channel, mc.campaign_cost,
           SUM(st.total_revenue) AS revenue_during
    FROM marketing_campaigns mc
    JOIN vehicles v ON v.brand = mc.brand
    JOIN sales_transactions st
          ON st.vehicle_id = v.vehicle_id
         AND st.transaction_date BETWEEN mc.start_date AND mc.end_date
    GROUP BY mc.campaign_id, mc.campaign_name, mc.brand,
             mc.campaign_channel, mc.campaign_cost
)
SELECT campaign_name, brand, campaign_channel,
       campaign_cost, revenue_during,
       ROUND((revenue_during - campaign_cost) / NULLIF(campaign_cost,0), 2) AS roi
FROM campaign_rev
ORDER BY roi DESC;


-- ---------------------------------------------------------------------------
-- Q17. Satisfaction band vs repeat-purchase behaviour
-- ---------------------------------------------------------------------------
WITH svc AS (
    SELECT customer_id, AVG(customer_satisfaction_score) AS avg_csat,
           COUNT(*) AS service_visits
    FROM after_sales_service
    GROUP BY customer_id
),
purch AS (
    SELECT customer_id, COUNT(*) AS purchases
    FROM sales_transactions
    GROUP BY customer_id
)
SELECT
    CASE WHEN s.avg_csat >= 4.5 THEN 'High CSAT (4.5+)'
         WHEN s.avg_csat >= 3.5 THEN 'Medium CSAT'
         ELSE 'Low CSAT (<3.5)' END AS csat_band,
    COUNT(*)                          AS customers,
    ROUND(AVG(p.purchases), 2)        AS avg_purchases,
    ROUND(AVG(s.service_visits), 1)   AS avg_service_visits
FROM svc s
JOIN purch p ON p.customer_id = s.customer_id
GROUP BY 1
ORDER BY avg_purchases DESC;


-- ---------------------------------------------------------------------------
-- Q18. Brand market share over time (year × brand)
-- ---------------------------------------------------------------------------
WITH yearly AS (
    SELECT v.brand,
           EXTRACT(YEAR FROM st.transaction_date) AS yr,
           SUM(st.quantity) AS units
    FROM sales_transactions st
    JOIN vehicles v ON v.vehicle_id = st.vehicle_id
    GROUP BY v.brand, EXTRACT(YEAR FROM st.transaction_date)
)
SELECT brand, yr, units,
       ROUND(100.0 * units
           / SUM(units) OVER (PARTITION BY yr), 2) AS market_share_pct,
       DENSE_RANK() OVER (PARTITION BY yr ORDER BY units DESC) AS rank_in_year
FROM yearly
ORDER BY yr, rank_in_year;


-- ---------------------------------------------------------------------------
-- Q19. Company YoY units & revenue growth
-- ---------------------------------------------------------------------------
WITH yr AS (
    SELECT EXTRACT(YEAR FROM transaction_date) AS sales_year,
           SUM(quantity)      AS units,
           SUM(total_revenue) AS revenue
    FROM sales_transactions
    GROUP BY EXTRACT(YEAR FROM transaction_date)
)
SELECT sales_year, units, revenue,
       ROUND(100.0 * (units - LAG(units) OVER (ORDER BY sales_year))
           / NULLIF(LAG(units) OVER (ORDER BY sales_year),0), 1)   AS units_yoy_pct,
       ROUND(100.0 * (revenue - LAG(revenue) OVER (ORDER BY sales_year))
           / NULLIF(LAG(revenue) OVER (ORDER BY sales_year),0), 1) AS revenue_yoy_pct
FROM yr
ORDER BY sales_year;


-- ---------------------------------------------------------------------------
-- Q20. Executive summary — one-row dashboard
-- ---------------------------------------------------------------------------
WITH base AS (
    SELECT st.*, v.brand, v.vehicle_type, d.region
    FROM sales_transactions st
    JOIN vehicles v ON v.vehicle_id = st.vehicle_id
    JOIN dealers  d ON d.dealer_id  = st.dealer_id
)
SELECT
    (SELECT SUM(quantity)      FROM base)                                   AS total_units,
    (SELECT SUM(total_revenue) FROM base)                                   AS total_revenue,
    (SELECT brand  FROM base GROUP BY brand
        ORDER BY SUM(quantity) DESC LIMIT 1)                                AS top_brand,
    (SELECT vehicle_type FROM base GROUP BY vehicle_type
        ORDER BY SUM(quantity) DESC LIMIT 1)                                AS top_vehicle_type,
    (SELECT region FROM base GROUP BY region
        ORDER BY SUM(total_revenue) DESC LIMIT 1)                           AS top_region,
    (SELECT ROUND(100.0 * SUM(CASE WHEN payment_method='Credit' THEN 1 END)
        / COUNT(*),1) FROM base)                                            AS credit_penetration_pct;


